    first, closed = next_listing_check_state(
        0, ListingStatus.CLOSED, closed_at="", now="t1", threshold=2,
    )
    assert first == 1
    assert closed == ""
    second, closed = next_listing_check_state(
        first, ListingStatus.CLOSED, closed_at=closed, now="t2", threshold=2,
    )
    assert second == 2
    assert closed == "t2"


